def amicable_numbers_sum(n):
    def sum_divisors(num):
        total = 1 if num > 1 else 0
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                total += i + num // i
        return total

    amicable_pairs_sum = set()
    for i in range(2, n + 1):
        d_i = sum_divisors(i)
        if d_i != i and sum_divisors(d_i) == i and d_i <= n:
            pair_set = {i, d_i}
            amicable_pairs_sum.update(pair_set)

    return sum(amicable_pairs_sum)

